// Build lib/client.js: inline the vendored html-to-image (MIT) into the
// hand-written client source as a string evaluated in the preview's realm.
import { readFileSync, writeFileSync } from 'node:fs'

const root = new URL('../', import.meta.url)
const source = readFileSync(new URL('src/client.src.js', root), 'utf8')
const vendor = readFileSync(new URL('vendor/html-to-image.js', root), 'utf8')
  .replace(/\n\/\/# sourceMappingURL=.*$/m, '')
const marker = "/*__HTML_TO_IMAGE__*/''"
if (!source.includes(marker)) throw new Error('vendor marker missing in src/client.src.js')
const header = '/* Generated by scripts/build.mjs from src/client.src.js — do not edit. Includes html-to-image 1.11.13 (MIT, (c) bubkoo) as a string. */\n'
const output = header + source.replace(marker, () => JSON.stringify(vendor))
writeFileSync(new URL('lib/client.js', root), output)
console.log(`lib/client.js ${output.length} bytes`)
